BEGIN;

ALTER TABLE "person"
    ADD COLUMN "email_personal_verified_at" TIMESTAMPTZ(6),
    ADD COLUMN "email_university_verified_at" TIMESTAMPTZ(6);

CREATE TABLE "person_email_identity" (
    "person_email_identity_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "person_id" INTEGER NOT NULL,
    "email" VARCHAR(255) NOT NULL,
    "kind" VARCHAR(20) NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "person_email_identity_pkey" PRIMARY KEY ("person_email_identity_id"),
    CONSTRAINT "person_email_identity_email_key" UNIQUE ("email"),
    CONSTRAINT "person_email_identity_person_kind_key" UNIQUE ("person_id", "kind"),
    CONSTRAINT "person_email_identity_person_id_fkey" FOREIGN KEY ("person_id")
        REFERENCES "person"("person_id") ON DELETE CASCADE ON UPDATE NO ACTION,
    CONSTRAINT "person_email_identity_kind_check" CHECK ("kind" IN ('PERSONAL', 'UNIVERSITY'))
);
INSERT INTO "person_email_identity" ("person_id", "email", "kind")
SELECT "person_id", lower(trim("email_personal")), 'PERSONAL'
FROM "person" WHERE "email_personal" IS NOT NULL AND trim("email_personal") <> ''
UNION ALL
SELECT "person_id", lower(trim("email_university")), 'UNIVERSITY'
FROM "person" WHERE "email_university" IS NOT NULL AND trim("email_university") <> '';

CREATE TABLE "non_member_registration" (
    "non_member_registration_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "person_id" INTEGER NOT NULL,
    "application_data" JSONB NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "non_member_registration_pkey" PRIMARY KEY ("non_member_registration_id"),
    CONSTRAINT "non_member_registration_person_id_key" UNIQUE ("person_id"),
    CONSTRAINT "non_member_registration_person_id_fkey" FOREIGN KEY ("person_id")
        REFERENCES "person"("person_id") ON DELETE RESTRICT ON UPDATE NO ACTION
);

CREATE TABLE "email_verification_challenge" (
    "email_verification_challenge_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "person_id" INTEGER NOT NULL,
    "purpose" VARCHAR(32) NOT NULL,
    "email" VARCHAR(255) NOT NULL,
    "code_hash" VARCHAR(64) NOT NULL,
    "sent_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "expires_at" TIMESTAMPTZ(6) NOT NULL,
    "attempts" INTEGER NOT NULL DEFAULT 0,
    "consumed_at" TIMESTAMPTZ(6),
    CONSTRAINT "email_verification_challenge_pkey" PRIMARY KEY ("email_verification_challenge_id"),
    CONSTRAINT "email_verification_challenge_person_purpose_key" UNIQUE ("person_id", "purpose"),
    CONSTRAINT "email_verification_challenge_person_id_fkey" FOREIGN KEY ("person_id")
        REFERENCES "person"("person_id") ON DELETE CASCADE ON UPDATE NO ACTION,
    CONSTRAINT "email_verification_challenge_purpose_check" CHECK ("purpose" = 'UNIVERSITY'),
    CONSTRAINT "email_verification_challenge_attempts_check" CHECK ("attempts" BETWEEN 0 AND 5)
);
CREATE INDEX "email_verification_challenge_expires_at_idx" ON "email_verification_challenge"("expires_at");

CREATE TABLE "pending_signup" (
    "pending_signup_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "person_id" INTEGER NOT NULL,
    "registration_type" VARCHAR(20) NOT NULL,
    "application_data" JSONB NOT NULL,
    "committees" JSONB NOT NULL DEFAULT '[]'::jsonb,
    "global_roles" JSONB NOT NULL DEFAULT '[]'::jsonb,
    "expires_at" TIMESTAMPTZ(6) NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pending_signup_pkey" PRIMARY KEY ("pending_signup_id"),
    CONSTRAINT "pending_signup_person_id_key" UNIQUE ("person_id"),
    CONSTRAINT "pending_signup_person_id_fkey" FOREIGN KEY ("person_id")
        REFERENCES "person"("person_id") ON DELETE CASCADE ON UPDATE NO ACTION,
    CONSTRAINT "pending_signup_registration_type_check" CHECK ("registration_type" IN ('MEMBER', 'NON_MEMBER'))
);
CREATE INDEX "pending_signup_expires_at_idx" ON "pending_signup"("expires_at");

CREATE TABLE "revoked_auth_token" (
    "token_hash" VARCHAR(64) NOT NULL,
    "expires_at" TIMESTAMPTZ(6) NOT NULL,
    "revoked_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "revoked_auth_token_pkey" PRIMARY KEY ("token_hash")
);
CREATE INDEX "revoked_auth_token_expires_at_idx" ON "revoked_auth_token"("expires_at");

ALTER TABLE "membership_request_committee"
    ADD COLUMN "approval_scope" VARCHAR(32) NOT NULL DEFAULT 'COMMITTEE';
ALTER TABLE "membership_request_committee"
    ADD CONSTRAINT "membership_request_committee_approval_scope_check"
    CHECK ("approval_scope" IN ('COMMITTEE', 'DEVELOPER_COMMITTEES', 'CLUB'));

CREATE TABLE "membership_request_global_role" (
    "membership_request_global_role_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "membership_request_id" INTEGER NOT NULL,
    "role_code" TEXT NOT NULL,
    "status" "MembershipCommitteeDecision" NOT NULL DEFAULT 'PENDING',
    "decided_by_member_id" INTEGER,
    "decided_at" TIMESTAMPTZ(6),
    CONSTRAINT "membership_request_global_role_pkey" PRIMARY KEY ("membership_request_global_role_id"),
    CONSTRAINT "membership_request_global_role_request_role_key" UNIQUE ("membership_request_id", "role_code"),
    CONSTRAINT "membership_request_global_role_request_fkey" FOREIGN KEY ("membership_request_id")
        REFERENCES "membership_request"("membership_request_id") ON DELETE CASCADE ON UPDATE NO ACTION,
    CONSTRAINT "membership_request_global_role_role_fkey" FOREIGN KEY ("role_code")
        REFERENCES "role"("role_code") ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT "membership_request_global_role_reviewer_fkey" FOREIGN KEY ("decided_by_member_id")
        REFERENCES "member"("member_id") ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT "membership_request_global_role_allowed_check"
        CHECK ("role_code" IN ('ADVISOR', 'DEVELOPER_COMMITTEES_LEADER')),
    CONSTRAINT "membership_request_global_role_decision_check" CHECK (
        ("status" = 'PENDING' AND "decided_by_member_id" IS NULL AND "decided_at" IS NULL)
        OR ("status" IN ('APPROVED', 'REJECTED') AND "decided_by_member_id" IS NOT NULL AND "decided_at" IS NOT NULL)
    )
);
CREATE INDEX "membership_request_global_role_role_status_idx"
    ON "membership_request_global_role"("role_code", "status", "membership_request_id");

INSERT INTO "role" ("role_code", "description", "is_privileged")
VALUES ('DEVELOPER_COMMITTEES_LEADER', 'Developer committees overall leader', true)
ON CONFLICT ("role_code") DO NOTHING;

INSERT INTO "permission" ("code", "description", "scope", "is_sensitive") VALUES
    ('applications.club_leaders.decide', 'Approve committee leader and developer lead applications', 'global', true),
    ('applications.developer_leaders.decide', 'Approve developer committee leader applications', 'global', true),
    ('developer_committees.dashboard.view', 'View developer committees leadership dashboard', 'global', false)
ON CONFLICT ("code") DO NOTHING;

INSERT INTO "role_permission" ("role_code", "code") VALUES
    ('GROUP_LEADER', 'applications.club_leaders.decide'),
    ('GROUP_CO_LEADER', 'applications.club_leaders.decide'),
    ('DEVELOPER_COMMITTEES_LEADER', 'applications.developer_leaders.decide'),
    ('DEVELOPER_COMMITTEES_LEADER', 'developer_committees.dashboard.view')
ON CONFLICT ("role_code", "code") DO NOTHING;

-- Committee dashboard data is for committee leadership. Members can use the
-- Minbar dashboard and must not read the entire committee roster and work data.
DELETE FROM "committee_permission"
WHERE "code" = 'dashboard.view' AND "committee_role" = 'Member';

-- Keep ordinary member applications committee-scoped, and route leader
-- applications to the appropriate global approval tier in application code.
INSERT INTO "committee_permission" ("committee_id", "committee_role", "code", "applies_to", "include_sub_committees")
SELECT c."committee_id", p."committee_role", 'applications.decide', 'own', false
FROM "committee" c
CROSS JOIN (VALUES ('Leader'), ('Co-Leader')) AS p("committee_role")
ON CONFLICT DO NOTHING;

-- Project Management is a supported committee and needs a stable backend code.
INSERT INTO "committee" ("committee_code", "committee_name")
VALUES ('PM', 'Project Management')
ON CONFLICT ("committee_code") DO NOTHING;

INSERT INTO "committee_permission" ("committee_id", "committee_role", "code", "applies_to", "include_sub_committees")
SELECT c."committee_id", p."committee_role", 'applications.decide', 'own', false
FROM "committee" c
CROSS JOIN (VALUES ('Leader'), ('Co-Leader')) AS p("committee_role")
WHERE c."committee_code" = 'PM'
ON CONFLICT DO NOTHING;

COMMIT;
